export default function TaskInterface({task, act}) {
  const t = task || {};
  const m = t.merchant || {};
  const intent = t.intent || {};
  const list = value => Array.isArray(value) ? value : [];
  const text = value => value == null ? 'Unknown' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  const overview = !task || t.status === 'not_started';
  const busy = !!t.progress || ['working','created','submitting'].includes(t.status);
  const locked = overview || busy || !!t.receipt;
  const [chosenMethod, setChosenMethod] = React.useState(null);
  const [chosenReason, setChosenReason] = React.useState(null);
  const methods = list(m.methods).filter(x => ['print_label','qr_dropoff'].includes(x.value));
  const reasons = list(m.reasons).filter(x => x.value);
  const lines = list(m.lines);
  const checks = list(t.checks);
  const selected = Array.isArray(m.selectedLines) ? m.selectedLines.map(x => x && typeof x === 'object' ? x.id : x) : null;
  const method = intent.method || chosenMethod || m.method || '';
  const reason = t.reason || chosenReason || '';
  const destination = intent.refundDestination || 'original_payment';
  const methodLabel = value => ({print_label:'Print a shipping label',qr_dropoff:'Printer-free QR drop-off'}[value]) || (methods.find(x => x.value === value) || {}).label || text(value);
  const destinationLabel = value => ({original_payment:'Original payment method',store_credit:'Store credit'}[value]) || (list(m.destinations).find(x => x.value === value) || {}).label || text(value);
  const money = value => {
    if (typeof value !== 'number' || !Number.isFinite(value) || !m.currency) return 'Unknown';
    try { return new Intl.NumberFormat('en-US',{style:'currency',currency:m.currency}).format(value / 100); }
    catch (_) { return String(value / 100) + ' ' + m.currency; }
  };
  const itemConflict = selected !== null && lines.some(x => {
    const identity = (text(x.name) + ' ' + text(x.id)).toLowerCase();
    const isShoe = identity.includes('red') && identity.includes('shoe');
    return selected.includes(x.id) ? !isShoe : isShoe;
  });
  const methodConflict = !!method && !!m.method && method !== m.method;
  const reasonConflict = !!reason && m.reason != null && reason !== m.reason;
  const conflict = t.status === 'conflict' || (m.refundDestination != null && destination !== m.refundDestination) || methodConflict || reasonConflict || itemConflict || checks.some(x => ['conflict','failed','fail','mismatch','error'].includes(x.status));
  const unknown = !m.method || !m.refundDestination || !m.currency || m.deductionCents == null || m.expectedRefundCents == null || selected === null;
  const discovery = t.discovery || {};
  const screens = list(discovery.screens);
  const flows = list(discovery.flows);
  const detail = (methods.find(x => x.value === method) || {}).detail;
  const status = t.receipt ? 'Receipt available. See the host’s separately verified completion result.' : busy ? 'Working. Waiting for updated source values; controls are locked.' : overview ? 'Overview only. No return has been submitted.' : t.error ? 'Source review needs attention. No completion is claimed.' : conflict ? 'Source conflict. Requested choices and observed terms do not match; submission is blocked.' : 'Review current source values. Validation is not submission.';
  function choose(key, value) {
    if (locked || !value) return;
    if (key === 'method') setChosenMethod(value);
    if (key === 'reason') setChosenReason(value);
    act('choice', {[key]:value});
  }
  function check(repair) { if (!locked) act('check',{repair}); }
  const terms = <dl className="generated-terms">
    <div><dt>Observed return method</dt><dd>{methodLabel(m.method)}</dd></div>
    <div><dt>Method fee / deduction</dt><dd>{money(m.deductionCents)}</dd></div>
    <div><dt>Observed refund destination</dt><dd>{destinationLabel(m.refundDestination)}</dd></div>
    <div><dt>Requested refund destination</dt><dd>{destinationLabel(destination)}</dd></div>
    <div className="generated-total"><dt>Expected refund</dt><dd>{money(m.expectedRefundCents)}</dd></div>
  </dl>;
  return <main className="generated-root">
    <header className="generated-header">
      <p className="generated-eyebrow">Merchant sandbox · Synthetic records only</p>
      <h1>{overview ? 'Explore your return options' : 'Review your return'}</h1>
      <p className="generated-lead">Return only the red shoes. Keep the jacket. Refund original payment.</p>
    </header>
    <div className="generated-status" role="status" aria-live="polite" aria-atomic="true">{status}</div>
    {!overview && conflict && <section className="generated-conflict" aria-labelledby="generated-conflict-title">
      <p className="generated-eyebrow">Source conflict · Submission blocked</p>
      <h2 id="generated-conflict-title">Your choices and source do not match</h2>
      <p>Changing the return method can change the source refund destination. Your requested destination remains unchanged.</p>
      <div className="generated-grid">
        <section className="generated-comparison"><h3>Requested refund destination</h3><p>{destinationLabel(destination)}</p></section>
        <section className="generated-comparison"><h3>Observed refund destination</h3><p>{destinationLabel(m.refundDestination)}</p></section>
      </div>
      {terms}
      {methodConflict && <p>Requested return method: {methodLabel(method)}<br />Observed return method: {methodLabel(m.method)}</p>}
      {reasonConflict && <p>Requested return reason: {text(reason)}<br />Observed return reason: {text(m.reason)}</p>}
      {itemConflict && <p>Requested items: return only red shoes; keep jacket.<br />Observed selected items: {selected.map(id => (lines.find(x => x.id === id) || {}).name || text(id)).join(', ') || 'None'}</p>}
      <button type="button" disabled={locked} onClick={() => check(true)}>Restore my choices</button>
      <p className="generated-small">Restoring checks the source again. It does not approve or submit the return.</p>
    </section>}
    {t.error && <section className="generated-error" role="alert"><h2>Source review message</h2><p>{text(t.error.message || t.error)}</p></section>}
    {overview ? <>
      <section className="generated-panel">
        <h2>Observed screens and flows</h2>
        {screens.length ? <ul className="generated-list">{screens.map((s,i) => <li key={s.id || i}><strong>{s.name || 'Observed screen'}</strong><p>{text(s.reachedState || s.stateLabel || 'Screen reached; completed return not verified.')}</p>{s.description && <p>{text(s.description)}</p>}</li>)}</ul> : <p>Returns | Merchant sandbox — item choices, reason, method, refund destination, and draft review were observed.</p>}
        {flows.length > 0 && <div className="generated-grid">{flows.map((f,i) => <section className="generated-mini" key={f.id || i}><h3>{f.name || f.label || 'Discovered flow'}</h3><p>{text(f.reachedState || f.stateLabel || 'Reached-state evidence not supplied.')}</p><p className="generated-small">Informational only. No execution from this card.</p></section>)}</div>}
        <p className="generated-small">The initial read-only exploration blocked draft writes, limiting item and reason coverage. Later synthetic branch observations reached the draft states below. A completed return was not verified.</p>
      </section>
      <section className="generated-panel">
        <h2>Two observed method paths</h2>
        <div className="generated-grid">
          <section className="generated-mini"><p className="generated-tag">Reached: saved draft review</p><h3>Print a shipping label</h3><p>Only the red shoes were selected; the jacket was kept. The source showed Original payment method.</p><p>Print and attach the label, then drop off the parcel.</p><p className="generated-small">Draft only — submission and confirmation not verified.</p></section>
          <section className="generated-mini"><p className="generated-tag">Reached: saved draft with destination mismatch</p><h3>Printer-free QR drop-off</h3><p>Only the red shoes were selected; the jacket was kept. Changing to QR drop-off changed the source destination to Store credit despite the original-payment selection.</p><p>The source described a drop-off fee and showing a QR code at the counter.</p><p className="generated-small">Draft only — submission and confirmation not verified.</p></section>
        </div>
        <p className="generated-note">Method changes can affect fees and refund destination. Current task data supplies amounts after starting; historical draft observations are not current quotes.</p>
      </section>
      <section className="generated-panel"><h2>Supported task</h2><p>Return the red shoes, keep the jacket, refund original payment.</p><p>Use the host’s “Start this task” control to begin this specific task. Starting does not approve submission.</p></section>
    </> : <>
      <div className="generated-layout">
        <div>
          <section className="generated-panel"><p className="generated-eyebrow">01 · Items</p><h2>Return shoes · Keep jacket</h2><p>Your item instructions are fixed. The jacket is not offered for return.</p>
            {lines.length ? <ul className="generated-list">{lines.map((x,i) => <li key={x.id || i}><strong>{x.name || 'Unnamed source item'}</strong>{x.variant && <p>{text(x.variant)}</p>}<p className="generated-small">Observed source: {selected === null ? 'selection unknown' : selected.includes(x.id) ? 'selected for return' : 'not selected for return'}</p></li>)}</ul> : <p>Source items: Unknown</p>}
          </section>
          <section className="generated-panel"><p className="generated-eyebrow">02 · Requested choices</p><h2>How to handle the return</h2>
            <label className="generated-label" htmlFor="generated-reason">Return reason</label>
            <select id="generated-reason" value={reason} disabled={locked || !reasons.length} onChange={e => choose('reason',e.target.value)}>
              <option value="">Choose a reason</option>
              {reason && !reasons.some(x => x.value === reason) && <option value={reason}>{text(reason)}</option>}
              {reasons.map(x => <option key={x.value} value={x.value}>{x.label || x.value}</option>)}
            </select>
            {!reasons.length && <p className="generated-small">Available reasons are unknown.</p>}
            <label className="generated-label" htmlFor="generated-method">Return method</label>
            <select id="generated-method" value={method} disabled={locked || !methods.length} aria-describedby="generated-method-note" onChange={e => choose('method',e.target.value)}>
              <option value="">Choose a method</option>
              {method && !methods.some(x => x.value === method) && <option value={method}>{methodLabel(method)}</option>}
              {methods.map(x => <option key={x.value} value={x.value}>{x.label || methodLabel(x.value)}</option>)}
            </select>
            {!methods.length && <p className="generated-small">Available methods are unknown.</p>}
            <p id="generated-method-note" className="generated-note">Changing the method may change the source refund destination. Your original-payment preference stays unchanged. Review the refreshed source terms for conflicts.</p>
            {detail && <p>{text(detail)}</p>}
            {intent.noPrinter && <p className="generated-note">Your preference: no printer.</p>}
            <h3>Requested refund destination</h3><p>{destinationLabel(destination)}</p>
          </section>
        </div>
        <section className="generated-panel generated-review"><p className="generated-eyebrow">03 · Source review</p><h2>Current observed terms</h2><p className="generated-small">Source values are separate from requested choices.{busy ? ' Refresh in progress; these may be prior values.' : ''}</p>
          {terms}
          {unknown && <p className="generated-note">Some source terms are unknown. Validate to inspect them. Unknown terms must be resolved before approval.</p>}
          <button type="button" className="generated-primary" disabled={locked} onClick={() => check(false)}>Validate current terms</button>
          <p className="generated-small">Validation is not submission. The host handles exact approval, submission, and separately verified saved confirmation.</p>
        </section>
      </div>
      {checks.length > 0 && <section className="generated-panel"><h2>Source check details</h2><ul className="generated-list">{checks.map((c,i) => <li key={i}><div className="generated-check"><strong>{c.label || 'Source check'}</strong><span>{text(c.status)}</span></div><p>Expected: {text(c.expected)}<br />Observed: {text(c.observed)}</p></li>)}</ul></section>}
    </>}
    <footer className="generated-footer">Sandbox only · No production access. A saved draft is not a completed return.</footer>
  </main>;
}
